$ErrorActionPreference='SilentlyContinue';$host.UI.RawUI.WindowTitle='S100A8 apo rep1 progress - display only';$root=Split-Path -Parent (Split-Path -Parent $MyInvocation.MyCommand.Path);$rep=Join-Path $root 'systems\apo\rep1';$last=$null;$lastPoll=$null;$rate=$null
while($true){$now=Get-Date;$prod=Get-ChildItem -LiteralPath $rep -Filter 'md_100ns*.log' -File|Sort-Object LastWriteTime|Select-Object -Last 1;if($prod){$stage='apo rep1 production';$log=$prod;$target=100.0}elseif(Test-Path (Join-Path $rep 'npt_ext4ns.log')){$stage='apo rep1 extended NPT';$log=Get-Item (Join-Path $rep 'npt_ext4ns.log');$target=4.0}elseif(Test-Path (Join-Path $rep 'npt.log')){$stage='apo rep1 NPT';$log=Get-Item (Join-Path $rep 'npt.log');$target=1.0}else{$stage='apo rep1 NVT';$log=Get-Item (Join-Path $rep 'nvt.log');$target=0.5};$ns=0.0;if($log){$txt=(Get-Content $log.FullName -Tail 350)-join "`n";$m=[regex]::Matches($txt,'Step\s+Time\s+\d+\s+([0-9.]+)');if($m.Count){$ns=[double]$m[$m.Count-1].Groups[1].Value/1000}};if($last-ne$null-and$ns-gt$last){$dh=($now-$lastPoll).TotalHours;if($dh-gt 0){$x=($ns-$last)/$dh*24;if($rate-eq$null){$rate=$x}else{$rate=.25*$x+.75*$rate}}};$last=$ns;$lastPoll=$now;$pct=[math]::Min(100,100*$ns/$target);$bar=('#'*[math]::Floor($pct/2.5)).PadRight(40,'-');$cpu=(Get-CimInstance Win32_Processor|Measure-Object LoadPercentage -Average).Average;$gpu=(& nvidia-smi --query-gpu=utilization.gpu,memory.used,memory.total,temperature.gpu,power.draw --format=csv,noheader,nounits|Select-Object -First 1)-split ',';$gp=Get-Process -Name gmx -ErrorAction SilentlyContinue|Select-Object -First 1;Clear-Host;Write-Host 'S100A8 apo molecular dynamics' -ForegroundColor Cyan;Write-Host ('Updated: {0}'-f$now.ToString('yyyy-MM-dd HH:mm:ss'));Write-Host ('Stage: {0}'-f$stage);Write-Host ('[{0}] {1:N2}%  {2:N3}/{3:N1} ns'-f$bar,$pct,$ns,$target);if($rate){Write-Host ('Speed: {0:N1} ns/day'-f$rate)};Write-Host ('CPU: {0}%  GPU: {1}%  VRAM: {2}/{3} MB  temp: {4} C'-f$cpu,$gpu[0].Trim(),$gpu[1].Trim(),$gpu[2].Trim(),$gpu[3].Trim());if($gp){Write-Host ('GROMACS RUNNING PID {0}'-f$gp.Id) -ForegroundColor Green}else{Write-Host 'GROMACS between stages / stopped' -ForegroundColor Yellow};Write-Host 'Closing this display does not stop the simulation.' -ForegroundColor DarkGray;Start-Sleep 5}
